-- ===========================================
-- File: 001_schema.sql
-- ===========================================

-- GreenCar schema (PostgreSQL)
-- Chạy file này để tạo toàn bộ bảng và khóa ngoại.

CREATE TABLE "roles" (
  "role_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role_name" varchar UNIQUE
);

CREATE TABLE "users" (
  "user_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "email" varchar UNIQUE,
  "password" varchar,
  "phone" varchar,
  "license_no" varchar,
  "role_id" int,
  "created_at" timestamp
);

CREATE TABLE "vehicle_models" (
  "vehicle_model_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "brand" varchar,
  "seats" int,
  "horsepower" int,
  "range_km" int,
  "trunk_capacity" int,
  "airbags" int,
  "vehicle_type" varchar,
  "transmission" varchar
);

CREATE TABLE "locations" (
  "location_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "address" varchar,
  "city" varchar,
  "latitude" decimal,
  "longitude" decimal
);

CREATE TABLE "vehicles" (
  "vehicle_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vehicle_model_id" int,
  "license_plate" varchar UNIQUE,
  "status" varchar,
  "battery_level" int,
  "battery_health" int,
  "location_id" int
);

CREATE TABLE "vehicle_images" (
  "image_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vehicle_model_id" int,
  "image_url" varchar
);

CREATE TABLE "rental_plans" (
  "rental_plan_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "duration_type" varchar,
  "max_km" int,
  "overtime_price" decimal,
  "over_km_price" decimal
);

CREATE TABLE "pricing" (
  "pricing_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vehicle_model_id" int,
  "rental_plan_id" int,
  "price" decimal
);

CREATE TABLE "bookings" (
  "booking_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "vehicle_id" int,
  "rental_plan_id" int,
  "start_time" timestamp,
  "end_time" timestamp,
  "actual_start_time" timestamp,
  "actual_end_time" timestamp,
  "planned_km" int,
  "actual_km" int,
  "deposit_amount" decimal,
  "overtime_fee" decimal,
  "over_km_fee" decimal,
  "extra_fee" decimal,
  "extra_fee_description" text,
  "total_price" decimal,
  "status" varchar,
  "payment_method" varchar(20),
  "owner_note" text,
  "created_at" timestamp
);

CREATE TABLE "payments" (
  "payment_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int,
  "amount" decimal,
  "payment_method" varchar,
  "payment_status" varchar,
  "paid_at" timestamp
);

CREATE TABLE "reviews" (
  "review_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "vehicle_model_id" int,
  "booking_id" int UNIQUE,
  "rating" int,
  "comment" text,
  "created_at" timestamp
);

CREATE TABLE "vehicle_features" (
  "feature_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "feature_name" varchar
);

CREATE TABLE "vehicle_model_features" (
  "vehicle_model_id" int,
  "feature_id" int
);

CREATE TABLE "vehicle_specs" (
  "spec_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vehicle_model_id" int,
  "spec_name" varchar,
  "spec_value" varchar
);

-- Foreign keys (thứ tự theo dependency)
ALTER TABLE "users" ADD FOREIGN KEY ("role_id") REFERENCES "roles" ("role_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "vehicles" ADD FOREIGN KEY ("vehicle_model_id") REFERENCES "vehicle_models" ("vehicle_model_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "vehicles" ADD FOREIGN KEY ("location_id") REFERENCES "locations" ("location_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "vehicle_images" ADD FOREIGN KEY ("vehicle_model_id") REFERENCES "vehicle_models" ("vehicle_model_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "pricing" ADD FOREIGN KEY ("vehicle_model_id") REFERENCES "vehicle_models" ("vehicle_model_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "pricing" ADD FOREIGN KEY ("rental_plan_id") REFERENCES "rental_plans" ("rental_plan_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "bookings" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "bookings" ADD FOREIGN KEY ("vehicle_id") REFERENCES "vehicles" ("vehicle_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "bookings" ADD FOREIGN KEY ("rental_plan_id") REFERENCES "rental_plans" ("rental_plan_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "payments" ADD FOREIGN KEY ("booking_id") REFERENCES "bookings" ("booking_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "vehicle_model_features" ADD FOREIGN KEY ("vehicle_model_id") REFERENCES "vehicle_models" ("vehicle_model_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "vehicle_model_features" ADD FOREIGN KEY ("feature_id") REFERENCES "vehicle_features" ("feature_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "vehicle_specs" ADD FOREIGN KEY ("vehicle_model_id") REFERENCES "vehicle_models" ("vehicle_model_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "reviews" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "reviews" ADD FOREIGN KEY ("vehicle_model_id") REFERENCES "vehicle_models" ("vehicle_model_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "reviews" ADD FOREIGN KEY ("booking_id") REFERENCES "bookings" ("booking_id") DEFERRABLE INITIALLY IMMEDIATE;


-- ===========================================
-- File: 002_migration_001.sql
-- ===========================================

-- =============================================================
--  GreenCar — Migration 001
--  Chạy SAU schema gốc (xe dien (1).sql)
--  psql -U <user> -d <dbname> -f migration_001.sql
-- =============================================================

BEGIN;

-- 1. Thêm owner_id vào vehicles (chủ xe của từng xe)
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS owner_id INT REFERENCES users(user_id);

-- 2. Thêm cccd vào users
ALTER TABLE users ADD COLUMN IF NOT EXISTS cccd VARCHAR;

-- 3. Thêm reviewer_name vào reviews (tên người review, lưu denormalized)
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS reviewer_name VARCHAR;

-- 4. Thêm note (lời nhắn) vào bookings
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS customer_note TEXT;

-- 5. Thêm delivery_type và delivery_address vào bookings
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS delivery_type VARCHAR DEFAULT 'self';
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS delivery_address TEXT;

-- 6. Bảng conversations (index cuộc trò chuyện theo booking)
CREATE TABLE IF NOT EXISTS conversations (
  conversation_id  INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id       INT REFERENCES bookings(booking_id) UNIQUE,
  vehicle_id       INT REFERENCES vehicles(vehicle_id) ON DELETE CASCADE,
  customer_id      INT REFERENCES users(user_id),
  owner_id         INT REFERENCES users(user_id),
  last_message_at  TIMESTAMPTZ DEFAULT now(),
  created_at       TIMESTAMPTZ DEFAULT now()
);

-- 7. Bảng messages (tin nhắn trong chat)
CREATE TABLE IF NOT EXISTS messages (
  message_id      INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  conversation_id INT REFERENCES conversations(conversation_id) ON DELETE CASCADE,
  sender_id       INT REFERENCES users(user_id),
  content         TEXT NOT NULL,
  is_read         BOOLEAN DEFAULT FALSE,
  created_at      TIMESTAMPTZ DEFAULT now()
);

-- Index để query nhanh tin nhắn theo conversation
CREATE INDEX IF NOT EXISTS idx_messages_conversation_id ON messages(conversation_id);
CREATE INDEX IF NOT EXISTS idx_messages_sender_id ON messages(sender_id);
CREATE INDEX IF NOT EXISTS idx_conversations_customer_id ON conversations(customer_id);
CREATE INDEX IF NOT EXISTS idx_conversations_owner_id ON conversations(owner_id);

COMMIT;


-- ===========================================
-- File: 003_posts.sql
-- ===========================================

CREATE TABLE IF NOT EXISTS posts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title VARCHAR(255) NOT NULL,
    content TEXT NOT NULL,
    author_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_posts_author_id ON posts(author_id);
CREATE INDEX idx_posts_created_at ON posts(created_at DESC);


-- ===========================================
-- File: 004_blog.sql
-- ===========================================

CREATE TABLE IF NOT EXISTS blog_categories (
  category_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar NOT NULL,
  slug varchar UNIQUE NOT NULL
);

CREATE TABLE IF NOT EXISTS blog_posts (
  post_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id INT REFERENCES users(user_id),
  category_id INT REFERENCES blog_categories(category_id),
  title varchar NOT NULL,
  slug varchar UNIQUE NOT NULL,
  excerpt text DEFAULT '',
  content text DEFAULT '',
  cover_image varchar DEFAULT '',
  status varchar DEFAULT 'draft',
  reject_reason varchar DEFAULT '',
  published_at timestamp,
  created_at timestamp,
  updated_at timestamp
);

