-- ===========================================
-- File: 009_booking_constraints.sql
-- ===========================================

-- 007_booking_constraints.sql
-- Kích hoạt extension btree_gist để có thể so sánh dấu '=' cho cột số nguyên (vehicle_id) kết hợp với '&&' cho tsrange
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- Thêm Exclude Constraint vào bảng bookings
ALTER TABLE bookings 
ADD CONSTRAINT exclude_overlapping_bookings
EXCLUDE USING gist (
    vehicle_id WITH =, 
    tsrange(start_time, end_time) WITH &&
)
WHERE (status != 'cancelled');

-- Performance optimization indexes
CREATE INDEX IF NOT EXISTS idx_bookings_vehicle_id ON bookings(vehicle_id);
CREATE INDEX IF NOT EXISTS idx_bookings_user_id ON bookings(user_id);
CREATE INDEX IF NOT EXISTS idx_vehicles_owner_id ON vehicles(owner_id);
CREATE INDEX IF NOT EXISTS idx_vehicles_vehicle_model_id ON vehicles(vehicle_model_id);
CREATE INDEX IF NOT EXISTS idx_reviews_vehicle_model_id ON reviews(vehicle_model_id);
CREATE INDEX IF NOT EXISTS idx_vehicle_images_vehicle_model_id ON vehicle_images(vehicle_model_id);
CREATE INDEX IF NOT EXISTS idx_pricing_vehicle_model_id ON pricing(vehicle_model_id);

-- License verification columns
ALTER TABLE users ADD COLUMN IF NOT EXISTS license_front_url VARCHAR;
ALTER TABLE users ADD COLUMN IF NOT EXISTS license_back_url VARCHAR;
ALTER TABLE users ADD COLUMN IF NOT EXISTS license_status VARCHAR DEFAULT 'unverified';
ALTER TABLE users ADD COLUMN IF NOT EXISTS license_reject_reason TEXT;

